import React, { useState } from "react";
import { Navigate } from 'react-router-dom';
import Header from "/src/components/Header";
import Info from "/src/components/info";
import Form from "/src/components/form";
import Place from "/src/components/place";
import Footer from "/src/components/Footer";
import { useDispatch } from "react-redux";
import { useAuth } from "use-auth";
import { removeUser } from "userSlice";


const API_KEY = "e5832fe7fa724f039e8a644e5697a808";

function Home() {
  const dispatch = useDispatch();
  const { isAuth, email } = useAuth();
  const [currentForm, setCurrentForm] = useState("login");
  const [state, setState] = useState({
    temp: undefined,
    ip: undefined,
    city: undefined,
    country_name: undefined,
    state_prov: undefined,
    hostname: undefined,
    error: undefined,
  });

  const toggleForm = (formName) => {
    setCurrentForm(formName);
  };

  const gettingPlace = async (e) => {
    e.preventDefault();
    const Ip = e.target.elements.ip.value;
    const api_url = await fetch(
      `https://api.ipgeolocation.io/ipgeo?apiKey=${API_KEY}&ip=${Ip}`
    );
    const data = await api_url.json();
    console.log(data);

    if (Ip) {
      setState({
        ip: data.ip,
        city: data.city,
        country_name: data.country_name,
        state_prov: data.state_prov,
        hostname: data.hostname,
        error: "",
      });
    }
  };

  return (
    <>(
        <div className="App">
          <Header />
          <Info />
          <Footer />
          <Form placeIp={gettingPlace} />
          <Place
            ip={state.ip}
            city={state.city}
            country_name={state.country_name}
            state_prov={state.state_prov}
            hostname={state.hostname}
            error={state.error}
          />
          <button onClick={() => dispatch(removeUser())}>
          </button>
        </div>
      ) : (
        <Navigate to="/login" />
      )}
    </>
  );
}

export default Home;
